  return (
    <>
      <button
        onClick={() => {
          setNumber((n) => n + 1);
          setNumber((n) => n + 1);
        }}
      >
        {number}
      </button>
      <button
        onClick={() => {
          setNumber(number + 1);
          setNumber((n) => n + 1);
        }}
      >
        {number}
      </button>
      <button
        onClick={() => {
          setUnchanged(0);
        }}
      >
        {unchanged}
      </button>
    </>
  );
}
